  col += base * 0.18 * soft;
  col = mix(col, bg * 1.15 + 0.08, fres * 0.28);
  col += vec3(1.0, 0.97, 0.9) * (spec * 1.1 + sheen * 0.25);
  return vec4(col, alpha);
